      <table data-testid="all-invoices-table">
        <caption>All invoices across every project</caption>
        <thead>
          <tr>
            <th scope="col">Invoice</th>
            <th scope="col">Project</th>
            <th scope="col">Amount</th>
            <th scope="col">Status</th>
            <th scope="col">Issued</th>
            <th scope="col">Due</th>
